<template>
  <div class="charger-listing">
    <h2>Charging Stations</h2>
    <div class="actions">
      <button @click="showAddForm = true">Add New Charger</button>
      <button @click="logout">Logout</button>
    </div>

    <div v-if="showAddForm" class="form-container">
      <h3>Add / Edit Charger</h3>
      <form @submit.prevent="saveCharger">
        <input v-model="form.name" type="text" placeholder="Name" required />
        <input v-model.number="form.location.latitude" type="number" placeholder="Latitude" step="any" required />
        <input v-model.number="form.location.longitude" type="number" placeholder="Longitude" step="any" required />
        <select v-model="form.status" required>
          <option>Active</option>
          <option>Inactive</option>
        </select>
        <input v-model.number="form.powerOutput" type="number" placeholder="Power Output (kW)" required />
        <input v-model="form.connectorType" type="text" placeholder="Connector Type" required />
        <div class="form-buttons">
          <button type="submit">Save</button>
          <button type="button" @click="cancelForm">Cancel</button>
        </div>
      </form>
    </div>

    <div class="filters">
      <label>
        Status:
        <select v-model="filters.status">
          <option value="">All</option>
          <option>Active</option>
          <option>Inactive</option>
        </select>
      </label>
      <label>
        Connector Type:
        <input v-model="filters.connectorType" placeholder="Type" />
      </label>
      <label>
        Min Power Output (kW):
        <input v-model.number="filters.minPower" type="number" min="0" />
      </label>
      <button @click="applyFilters">Apply Filters</button>
      <button @click="clearFilters">Clear Filters</button>
    </div>

    <ul class="charger-list">
      <li v-for="charger in filteredChargers" :key="charger._id">
        <strong>{{ charger.name }}</strong> - {{ charger.status }}, {{ charger.powerOutput }} kW, {{ charger.connectorType }}
        <button @click="editCharger(charger)">Edit</button>
        <button @click="deleteCharger(charger._id)">Delete</button>
      </li>
    </ul>

    <p v-if="error" class="error">{{ error }}</p>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  data() {
    return {
      chargers: [],
      filteredChargers: [],
      error: '',
      showAddForm: false,
      editingId: null,
      form: {
        name: '',
        location: { latitude: 0, longitude: 0 },
        status: 'Active',
        powerOutput: 0,
        connectorType: ''
      },
      filters: {
        status: '',
        connectorType: '',
        minPower: 0
      }
    };
  },
  methods: {
    async fetchChargers() {
      this.error = '';
      try {
        const token = localStorage.getItem('token');
        if (!token) {
          this.$router.push('/');
          return;
        }
        const response = await axios.get('http://localhost:5000/api/charging-stations', {
          headers: { Authorization: `Bearer ${token}` }
        });
        this.chargers = response.data;
        this.applyFilters();
      } catch (err) {
        this.error = err.response?.data?.message || 'Failed to load chargers';
        if(err.response && err.response.status === 401){
          localStorage.removeItem('token');
          this.$router.push('/');
        }
      }
    },

    async saveCharger() {
      this.error = '';
      const token = localStorage.getItem('token');
      if (!token) {
        this.$router.push('/');
        return;
      }
      try {
        if (this.editingId) {
          await axios.put(`http://localhost:5000/api/charging-stations/${this.editingId}`, this.form, {
            headers: { Authorization: `Bearer ${token}` }
          });
        } else {
          await axios.post('http://localhost:5000/api/charging-stations', this.form, {
            headers: { Authorization: `Bearer ${token}` }
          });
        }
        this.showAddForm = false;
        this.editingId = null;
        this.clearForm();
        this.fetchChargers();
      } catch (err) {
        this.error = err.response?.data?.message || 'Failed to save charger';
      }
    },

    editCharger(charger) {
      this.showAddForm = true;
      this.editingId = charger._id;
      this.form = {
        name: charger.name,
        location: { latitude: charger.location.latitude, longitude: charger.location.longitude },
        status: charger.status,
        powerOutput: charger.powerOutput,
        connectorType: charger.connectorType
      };
    },

    cancelForm() {
      this.showAddForm = false;
      this.editingId = null;
      this.clearForm();
    },

    clearForm() {
      this.form = {
        name: '',
        location: { latitude: 0, longitude: 0 },
        status: 'Active',
        powerOutput: 0,
        connectorType: ''
      };
    },

    async deleteCharger(id) {
      this.error = '';
      const token = localStorage.getItem('token');
      if (!token) {
        this.$router.push('/');
        return;
      }
      if (confirm('Are you sure you want to delete this charger?')) {
        try {
          await axios.delete(`http://localhost:5000/api/charging-stations/${id}`, {
            headers: { Authorization: `Bearer ${token}` }
          });
          this.fetchChargers();
        } catch (err) {
          this.error = err.response?.data?.message || 'Failed to delete charger';
        }
      }
    },

    applyFilters() {
      this.filteredChargers = this.chargers.filter(charger => {
        if (this.filters.status && charger.status !== this.filters.status) return false;
        if (this.filters.connectorType && !charger.connectorType.toLowerCase().includes(this.filters.connectorType.toLowerCase())) return false;
        if (this.filters.minPower && charger.powerOutput < this.filters.minPower) return false;
        return true;
      });
    },

    clearFilters() {
      this.filters = { status: '', connectorType: '', minPower: 0 };
      this.applyFilters();
    },

    logout() {
      localStorage.removeItem('token');
      this.$router.push('/');
    }
  },
  mounted() {
    this.fetchChargers();
  }
};
</script>

<style scoped>
.charger-listing {
  max-width: 700px;
  margin: 20px auto;
  padding: 10px;
  box-shadow: 0 0 15px #ddd;
  border-radius: 8px;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background-color: #fff;
}

.actions {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
}

.actions button {
  padding: 8px 12px;
  border: none;
  border-radius: 4px;
  background-color: #1976d2;
  color: white;
  cursor: pointer;
}

.actions button:hover {
  background-color: #1565c0;
}

.form-container {
  margin-bottom: 20px;
}

form input, form select {
  width: calc(50% - 10px);
  margin: 5px;
  padding: 8px;
  border-radius: 4px;
  border: 1px solid #ccc;
  box-sizing: border-box;
}

.form-buttons {
  margin-top: 10px;
}

.form-buttons button {
  margin-right: 10px;
  padding: 8px 15px;
  border: none;
  border-radius: 4px;
  background-color: #1976d2;
  color: white;
  cursor: pointer;
}

.form-buttons button:hover {
  background-color: #1565c0;
}

.filters {
  margin-bottom: 15px;
}

.filters label {
  margin-right: 15px;
}

.charger-list {
  list-style:none;
  padding:0;
}

.charger-list li {
  padding: 10px;
  border-bottom: 1px solid #ddd;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.charger-list li button {
  margin-left: 10px;
  padding: 5px 10px;
  border: none;
  border-radius: 4px;
  background-color: #d32f2f;
  color: white;
  cursor: pointer;
}

.charger-list li button:hover {
  background-color: #b71c1c;
}

.error {
  color: red;
  margin-top: 10px;
}
</style>