<template>
  <div class="map-container">
    <h2>Charging Stations Map</h2>
    <button @click="logout" class="logout-btn">Logout</button>
    <div id="map" style="height: 600px;"></div>
  </div>
</template>

<script>
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import axios from 'axios';

export default {
  data() {
    return {
      map: null,
      markersLayer: null
    };
  },
  methods: {
    async fetchChargers() {
      const token = localStorage.getItem('token');
      if (!token) {
        this.$router.push('/');
        return;
      }
      try {
        const response = await axios.get('http://localhost:5000/api/charging-stations', {
          headers: { Authorization: `Bearer ${token}` }
        });
        return response.data;
      } catch (err) {
        if (err.response && err.response.status === 401) {
          localStorage.removeItem('token');
          this.$router.push('/');
        } else {
          alert('Failed to load charging stations');
        }
        return [];
      }
    },

    async populateMap() {
      const chargers = await this.fetchChargers();

      if (this.markersLayer) {
        this.markersLayer.clearLayers();
      } else {
        this.markersLayer = L.layerGroup().addTo(this.map);
      }

      chargers.forEach(charger => {
        const marker = L.marker([charger.location.latitude, charger.location.longitude]);
        marker.bindPopup(
          `<b>${charger.name}</b><br>Status: ${charger.status}<br>Power: ${charger.powerOutput} kW<br>Connector: ${charger.connectorType}`
        );
        this.markersLayer.addLayer(marker);
      });
    },

    logout() {
      localStorage.removeItem('token');
      this.$router.push('/');
    }
  },
  mounted() {
    this.map = L.map('map').setView([20, 0], 2); // World view
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap contributors',
      maxZoom: 18
    }).addTo(this.map);

    this.populateMap();
  }
};
</script>

<style scoped>
.map-container {
  max-width: 900px;
  margin: 20px auto;
  padding: 10px;
  box-shadow: 0 0 15px #ddd;
  border-radius: 8px;
  background-color: white;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  position: relative;
}

.logout-btn {
  position: absolute;
  top: 15px;
  right: 15px;
  z-index: 1000;
  padding: 8px 12px;
  border: none;
  border-radius: 4px;
  background-color: #d32f2f;
  color: white;
  cursor: pointer;
}

.logout-btn:hover {
  background-color: #b71c1c;
}
</style>